import{_ as p,r as n,o,c,e as a,a as l,s as r}from"./chunks/framework.CXcwiNg-.js";const _=JSON.parse('{"title":"Пользователи - October CMS - 3.x","titleTemplate":false,"description":"Узнайте об управлении пользователями в панели управления.","frontmatter":{"subtitle":"Узнайте об управлении пользователями в панели управления."},"headers":[{"level":2,"title":"Вспомогательный класс пользователя панели управления","slug":"вспомогательныи-класс-пользователя-панели-управления","link":"#вспомогательныи-класс-пользователя-панели-управления","children":[]},{"level":2,"title":"Группы","slug":"группы","link":"#группы","children":[]},{"level":2,"title":"Изменение пароля пользователя панели управления","slug":"изменение-пароля-пользователя-панели-управления","link":"#изменение-пароля-пользователя-панели-управления","children":[]}],"relativePath":"3.x/ru/extend/backend/users.md","filePath":"3.x/ru/extend/backend/users.md"}'),i={name:"3.x/ru/extend/backend/users.md"};function u(k,s,d,g,h,m){const e=n("pre-heading"),t=n("post-heading");return o(),c("div",null,[a(e),s[0]||(s[0]=l("h1",null,"Пользователи",-1)),a(t),s[1]||(s[1]=r(`<p>Управление пользователями панели управления работает с администраторами, где модель <code>Backend\\Models\\User</code> является контейнером, хранящим всю важную информацию о пользователе. Она включает такие функции, как роли, группы, разрешения, сброс пароля и ограничение попыток входа. Плагины также могут <a href="./permissions.html">регистрировать разрешения</a>, контролирующие доступ к функциям в панели управления.</p><h2 id="вспомогательныи-класс-пользователя-панели-управления"><a href="#вспомогательныи-класс-пользователя-панели-управления" class="header-anchor">#</a> Вспомогательный класс пользователя панели управления</h2><p>Глобальный фасад <code>BackendAuth</code> может использоваться для управления административными пользователями и в основном наследует класс <code>October\\Rain\\Auth\\Manager</code>. Для регистрации новой учётной записи администратора используйте метод <code>BackendAuth::register</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">register</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;first_name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Some&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;last_name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;User&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;login&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;someuser&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;some@website.tld&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;password&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;changeme&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;password_confirmation&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;changeme&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>BackendAuth::check</code> — это быстрый способ проверить, авторизован ли пользователь. Для возврата модели авторизованного пользователя используйте <code>BackendAuth::getUser</code>. Кроме того, активный пользователь будет доступен как <code>$this-&gt;user</code> внутри любого <a href="./../system/controllers.html">контроллера панели управления</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Returns true if signed in.</span>
<span class="token variable">$loggedIn</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">check</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Returns the signed in user</span>
<span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">getUser</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете найти пользователя по его логину с помощью метода <code>BackendAuth::findUserByLogin</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">findUserByLogin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;someuser&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете аутентифицировать пользователя, указав его логин и пароль с помощью <code>BackendAuth::authenticate</code>. Вы также можете аутентифицироваться как пользователь, просто передав модель <code>Backend\\Models\\User</code> в <code>BackendAuth::login</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Authenticate user by credentials</span>
<span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">authenticate</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;login&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;login&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;password&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;password&#39;</span><span class="token punctuation">)</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Sign in as a specific user</span>
<span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">login</span><span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="группы"><a href="#группы" class="header-anchor">#</a> Группы</h2><p>Группы пользователей используют модель <code>Backend\\Models\\UserGroup</code> и являются организационным инструментом для группировки администраторов. Они не связаны с <a href="./permissions.html">разрешениями пользователей</a> и предназначены исключительно для организационных целей, таких как уведомления.</p><p>Например, если вы хотите отправить электронное письмо всем пользователям в группе <code>Head Office Staff</code>, вы можете найти группу пользователей вместе с пользователями в этой группе.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$group</span> <span class="token operator">=</span> <span class="token class-name static-context">UserGroup</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;code&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;head-office-staff&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token variable">$group</span><span class="token operator">-&gt;</span><span class="token property">users</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;author.plugin:important_notification&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="изменение-пароля-пользователя-панели-управления"><a href="#изменение-пароля-пользователя-панели-управления" class="header-anchor">#</a> Изменение пароля пользователя панели управления</h2><p>Команда <code>october:passwd</code> позволяет изменить пароль администратора панели управления через командную строку. Это полезно, если вы потеряли доступ к установке October CMS или для изменения пароля учётной записи администратора по умолчанию.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan october:passwd username password
</code></pre></div><p>Первым аргументом вы можете передать либо логин, либо адрес электронной почты. Вторым аргументом вы можете опционально передать желаемый пароль, в противном случае вам будет предложено его ввести.</p>`,18))])}const v=p(i,[["render",u]]);export{_ as __pageData,v as default};
